import {CalendarPreferences,GoogleReadSession,CalendarReader,validClientId,calendarRange,eventsOnDay,tasksOnDay,calendarToday} from './calendar.js';
import {addDays,dateInZone} from './planning.js';
import {visibleItems,openItem,validDate} from './domain.js';
import {submitOnce,checkForm} from './forms.js';

export function createCalendarUI({storage,getState,getZone,onChange,onDisabled,openModal,closeModal,onEdit,toast,esc,icon,target=window,session=new GoogleReadSession({target}),reader=new CalendarReader(target.fetch?.bind(target)||globalThis.fetch?.bind(globalThis)),now=()=>Date.now()}){
  const prefs=new CalendarPreferences(storage);let date=calendarToday(getZone()),span=1,calendars=[],calendarsLoaded=false,events=[],updatedAt=0,ignored=0,error=prefs.error,busy=false,epoch=0,controller,lastKey='',activeKey='',refreshing=null;
  const clock=at=>new Intl.DateTimeFormat('pt-BR',{timeZone:getZone(),hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(at);
  const labelDay=d=>new Date(d+'T12:00:00Z').toLocaleDateString('pt-BR',{timeZone:'UTC',weekday:'long',day:'numeric',month:'long'});
  const notify=()=>onChange();
  function status(){if(error)return error;if(target.navigator?.onLine===false)return 'Sem conexão. Suas tarefas continuam disponíveis; os compromissos precisam de conexão para atualizar.';if(!prefs.value.clientId)return 'Configure a conexão para consultar sua agenda privada.';if(busy)return 'Consultando o Google Agenda…';if(session.accessToken&&calendarsLoaded)return 'Conectado para consulta nesta sessão.';if(updatedAt)return 'O acesso expirou. Reconecte para atualizar os compromissos.';return 'Conecte para consultar seus compromissos.';}
  function connection(){return `<section class="day-connection" aria-label="Conexão com Google Agenda"><div><strong>Google Agenda · somente leitura</strong><p role="status">${esc(status())}</p>${updatedAt?`<small>Última consulta: ${esc(new Date(updatedAt).toLocaleString('pt-BR',{timeZone:getZone(),dateStyle:'short',timeStyle:'short'}))}${!session.accessToken||error?' · dados podem estar desatualizados':''}</small>`:''}</div><div class="day-connection-actions">${session.accessToken&&calendarsLoaded?`<button type="button" class="btn secondary" data-action="calendar-refresh" ${busy?'disabled':''}>Atualizar</button><button type="button" class="textbtn" data-action="calendar-calendars" ${busy?'disabled':''}>Escolher agendas</button><button type="button" class="textbtn" data-action="calendar-disconnect">Desconectar</button>`:`<button type="button" class="btn secondary" data-action="calendar-connect" ${busy?'disabled':''}>${!prefs.value.clientId?'Configurar conexão':session.identity?'Conectar Google Agenda':'Preparar conexão com Google'}</button>`}</div></section>`;}
  function eventTime(event,d){if(event.allDay)return 'Dia inteiro';const first=dateInZone(new Date(event.start),getZone()),last=dateInZone(new Date(event.end),getZone());return `${first<d?'Continua':clock(event.start)} – ${last>d?'dia seguinte':clock(event.end)}`;}
  function eventMarkup(event,d){return `<article class="day-event" style="--event-color:${event.color}"><div class="day-entry-head"><span class="day-entry-time">${esc(eventTime(event,d))}</span><span class="day-entry-source">${esc(event.calendarName)} · Google</span></div><h3>${esc(event.title)}</h3>${event.location?`<p class="day-event-location">${icon('flag')}${esc(event.location)}</p>`:''}${event.description?`<details><summary>Detalhes</summary><p class="day-event-description">${esc(event.description)}</p></details>`:''}${event.link?`<a class="textbtn" href="${esc(event.link)}" target="_blank" rel="noopener noreferrer">Abrir no Google Agenda ${icon('arrow')}</a>`:''}</article>`;}
  function taskMarkup(task){const parent=task.parentId&&getState().items[task.parentId];return `<article class="day-task"><div class="day-entry-head"><span class="day-entry-time">${task.time?esc(task.time):'Sem horário'}</span><span class="day-entry-source">Tarefa · Retomar</span></div><div class="day-task-title"><h3>${esc(task.title)}</h3><button type="button" class="iconbtn" data-action="calendar-edit-task" data-id="${esc(task.id)}" aria-label="Gerenciar: ${esc(task.title)}">${icon('gear')}</button></div>${parent?`<p class="field-help">Subitem de ${esc(parent.title)}</p>`:''}</article>`;}
  function dayMarkup(d){
    const scheduled=eventsOnDay(events,d,getZone()),tasks=tasksOnDay(getState(),d),allDay=scheduled.filter(e=>e.allDay),timed=[...scheduled.filter(e=>!e.allDay).map(event=>({at:event.start,markup:eventMarkup(event,d)})),...tasks.map(task=>({at:task.time?Date.parse(d+'T'+task.time+':00Z'):Infinity,task,markup:taskMarkup(task)}))];
    // Ordena horários locais em conjunto, sem tratar um prazo sem hora como compromisso.
    for(const entry of timed)entry.sort=entry.task?(entry.task.time||'99:99'):(dateInZone(new Date(entry.at),getZone())<d?'00:00':clock(entry.at));
    timed.sort((a,b)=>a.sort.localeCompare(b.sort)||Number(!!b.task)-Number(!!a.task));
    return `<section class="day-column" aria-label="${esc(labelDay(d))}"><div class="day-column-heading"><h2>${esc(d===calendarToday(getZone())?'Hoje · '+labelDay(d):labelDay(d))}</h2><span>${tasks.length} ${tasks.length===1?'tarefa':'tarefas'} · ${scheduled.length} ${scheduled.length===1?'evento':'eventos'}</span></div>${allDay.map(e=>eventMarkup(e,d)).join('')}${timed.map(e=>e.markup).join('')}${!tasks.length&&!scheduled.length?`<p class="day-empty">${session.accessToken?'Nenhuma tarefa ou compromisso neste dia.':'Nenhuma tarefa neste dia. Conecte a agenda para consultar também os compromissos.'}</p>`:''}</section>`;
  }
  function page(){
    const tasks=visibleItems(getState()).filter(openItem),undated=tasks.filter(t=>!t.date).length,overdue=tasks.filter(t=>t.date&&t.date<calendarToday(getZone())).length;
    return `<div class="page-heading"><h1>Meu dia</h1><p>Tarefas e compromissos no seu horário. Fuso: ${esc(getZone())}.</p></div><section class="day-controls" aria-label="Período da agenda"><button type="button" class="iconbtn" data-action="calendar-prev" aria-label="Período anterior">${icon('left')}</button><div class="field"><label for="calendar-date">A partir de</label><input type="date" id="calendar-date" min="1900-01-01" max="2200-12-24" value="${date}"></div><div class="field"><label for="calendar-span">Período</label><select id="calendar-span"><option value="1" ${span===1?'selected':''}>Um dia</option><option value="7" ${span===7?'selected':''}>Sete dias</option></select></div><button type="button" class="iconbtn" data-action="calendar-next" aria-label="Próximo período">${icon('right')}</button><button type="button" class="textbtn" data-action="calendar-today">Hoje</button></section>${connection()}${ignored?`<p class="planning-warning">${ignored} evento(s) retornaram data ou horário inválido e não puderam ser exibidos.</p>`:''}<div class="day-grid ${span===7?'day-grid-week':''}">${Array.from({length:span},(_,i)=>dayMarkup(addDays(date,i))).join('')}</div><div class="day-other-tasks">${overdue?`<button type="button" class="textbtn" data-action="scope" data-scope="overdue">${overdue} tarefa(s) de dias anteriores</button>`:''}${undated?`<button type="button" class="textbtn" data-action="undated">${undated} tarefa(s) sem data</button>`:''}</div>`;
  }
  function settings(){return `<section class="settingscard"><div class="settings-heading"><span class="settings-icon">${icon('calendar')}</span><div><h2>Meu dia e Google Agenda</h2><p>Consulta opcional de compromissos, junto às tarefas.</p></div></div><p class="field-help">${prefs.value.enabled?'A visão Meu dia está disponível.':'A visão Meu dia está oculta. Seu planejamento continua disponível.'} A conexão do Google vale nesta sessão; as tarefas e o backup não dependem dela.</p>${prefs.error?`<p class="planning-warning">${esc(prefs.error)}</p>`:''}<button type="button" class="btn secondary" data-action="calendar-settings">Configurar agenda</button><details class="settings-details"><summary>Se eu quiser voltar à versão anterior?</summary><p>A versão 1.3, anterior à integração, está preservada. É possível restaurá-la sem mudar o formato dos dados de tarefas. Para apenas ocultar a integração neste aparelho, desative Meu dia nas opções acima.</p><a class="textbtn" href="https://github.com/Sosoft142/Retomar/tree/backup/retomar-1.3-antes-agenda-2026-11-11" target="_blank" rel="noopener noreferrer">Ver versão 1.3 preservada</a></details></section>`;}
  function reset(){epoch++;controller?.abort();session.clear();calendars=[];calendarsLoaded=false;events=[];updatedAt=0;ignored=0;lastKey='';activeKey='';busy=false;refreshing=null;}
  async function refresh(force=false){
    if(!prefs.value.enabled||!session.accessToken||!calendarsLoaded)return;
    if(target.navigator?.onLine===false){error='Sem conexão. As tarefas e a última consulta desta sessão continuam disponíveis.';notify();return;}
    const chosen=calendars.filter(c=>prefs.value.calendarIds?.includes(c.id)),key=JSON.stringify([date,span,getZone(),chosen.map(c=>c.id)]);
    if(refreshing&&activeKey===key)return refreshing;if(!force&&key===lastKey)return;
    const token=session.accessToken,generation=++epoch;controller?.abort();controller=new AbortController();activeKey=key;lastKey=key;busy=true;error='';notify();
    const request=(async()=>{try{
      const result=await reader.events(chosen,calendarRange(date,span,getZone()),token,controller.signal);
      if(generation!==epoch)return;events=result.events;ignored=result.ignored;updatedAt=now();lastKey=key;
    }catch(e){if(generation!==epoch)return;if(e.status===401)session.clear();error=e.name==='AbortError'?'Consulta cancelada.':e.message||'Não foi possível consultar a agenda.';}finally{if(generation===epoch){busy=false;refreshing=null;notify();}}})();refreshing=request;return request;
  }
  function configuration(){
    const root=openModal('Configurar Meu dia e Agenda',`<form id="calendar-settings-form"><p class="formerror" role="alert" tabindex="-1"></p><label class="planning-check"><input type="checkbox" id="calendar-enabled" ${prefs.value.enabled?'checked':''}><span>Mostrar Meu dia e a integração com Google Agenda</span></label><p class="field-help">Você pode usar Meu dia apenas com suas tarefas. Para consultar uma agenda privada, a conexão precisa de uma configuração inicial no Google.</p><details ${prefs.value.clientId?'':'open'} class="settings-details"><summary>Configuração da conexão com Google</summary><p class="field-help">Use um cliente OAuth do tipo Aplicativo da Web, com a API Google Calendar ativada e a origem <strong>https://sosoft142.github.io</strong> autorizada. O identificador abaixo é público; não cole senha, token nem segredo de cliente.</p><div class="field"><label for="google-client-id">ID público do cliente Google · opcional</label><input type="text" id="google-client-id" maxlength="250" autocomplete="off" spellcheck="false" value="${esc(prefs.value.clientId)}" placeholder="…apps.googleusercontent.com"></div><a class="textbtn" href="https://github.com/Sosoft142/Retomar/blob/main/docs/GOOGLE-AGENDA.md" target="_blank" rel="noopener noreferrer">Abrir instruções de configuração</a></details><p class="field-help">Somente os eventos e a lista de agendas serão consultados. Não há criação, edição ou exclusão de eventos. A autorização fica na memória desta sessão e não vai para o backup.</p><div class="dialogactions"><button type="button" class="btn secondary" id="calendar-settings-cancel">Cancelar</button><button type="submit" class="btn primary">Salvar opções</button></div></form>`);
    root.querySelector('#calendar-settings-cancel').onclick=()=>closeModal();
    root.querySelector('form').onsubmit=submitOnce(async e=>{if(!checkForm(e.target))return;const id=root.querySelector('#google-client-id').value.trim(),enabled=root.querySelector('#calendar-enabled').checked;try{
      if(id&&!validClientId(id))throw Error('Informe um ID público completo, terminado em .apps.googleusercontent.com.');
      const changed=id!==prefs.value.clientId;prefs.save({enabled,clientId:id,calendarIds:changed?null:prefs.value.calendarIds});if(changed||!enabled)reset();error='';closeModal(true);if(!enabled)onDisabled();notify();toast('Opções da agenda salvas neste aparelho.');
    }catch(e){const field=root.querySelector('.formerror');field.textContent=e.message;field.focus();}});
  }
  function chooseCalendars(){
    const root=openModal('Agendas exibidas',`<form><p class="formerror" role="alert"></p><p class="field-help">Escolha as agendas para consultar. Até 100 agendas podem ser selecionadas.</p><div class="calendar-choices">${calendars.map((c,i)=>`<label class="planning-check"><input type="checkbox" data-calendar-index="${i}" ${prefs.value.calendarIds?.includes(c.id)?'checked':''}><span><i class="calendar-dot" style="background:${c.color}"></i>${esc(c.name)}</span></label>`).join('')}</div><div class="dialogactions"><button type="button" class="btn secondary" id="calendar-choice-cancel">Cancelar</button><button type="submit" class="btn primary">Aplicar agendas</button></div></form>`);
    root.querySelector('#calendar-choice-cancel').onclick=()=>closeModal();root.querySelector('form').onsubmit=submitOnce(async()=>{try{const ids=[...root.querySelectorAll('[data-calendar-index]:checked')].map(n=>calendars[Number(n.dataset.calendarIndex)].id);prefs.save({...prefs.value,calendarIds:ids});events=[];updatedAt=0;lastKey='';closeModal(true);notify();await refresh();}catch(e){root.querySelector('.formerror').textContent=e.message;}});
  }
  async function connect(){
    if(!prefs.value.clientId){configuration();return;}
    if(!session.identity){busy=true;error='';notify();try{await session.prepare();toast('Conexão preparada. Toque em Conectar Google Agenda para autorizar sua conta.');}finally{busy=false;notify();}return;}
    const generation=++epoch;events=[];calendars=[];calendarsLoaded=false;updatedAt=0;lastKey='';error='';busy=true;
    // Inicia a janela diretamente no gesto; a consulta ocorre somente depois do consentimento.
    const auth=session.connect(prefs.value.clientId);notify();
    try{await auth;if(generation!==epoch)return;controller=new AbortController();const list=await reader.calendars(session.accessToken,controller.signal);if(generation!==epoch)return;
      const ids=prefs.value.calendarIds===null?list.filter(c=>c.primary).map(c=>c.id):prefs.value.calendarIds.filter(id=>list.some(c=>c.id===id));prefs.save({...prefs.value,calendarIds:ids});calendars=list;calendarsLoaded=true;busy=false;await refresh(true);
    }finally{if(generation===epoch){busy=false;notify();}}
  }
  async function action(name,data={}){
    try{
      if(name==='calendar-settings'){configuration();return;}
      if(name==='calendar-disconnect'){reset();error='';notify();toast('Agenda desconectada neste aparelho. Seus compromissos no Google foram preservados.');return;}
      if(name==='calendar-edit-task'){onEdit(data.id);return;}
      if(!prefs.value.enabled)return;
      if(['calendar-connect','calendar-refresh'].includes(name)&&target.navigator?.onLine===false)throw Error('Conecte à internet para consultar o Google Agenda. Suas tarefas continuam disponíveis.');
      if(name==='calendar-connect'){if(!busy)await connect();return;}
      if(name==='calendar-calendars'){chooseCalendars();return;}
      if(name==='calendar-refresh'){await refresh(true);return;}
      if(name==='calendar-prev'||name==='calendar-next'){const next=addDays(date,name==='calendar-prev'?-span:span);if(!validDate(next)||next>'2200-12-24')throw Error('O período está fora do intervalo disponível.');date=next;}
      else if(name==='calendar-today')date=calendarToday(getZone());
      else if(name==='calendar-date'){if(!validDate(data.value)||data.value>'2200-12-24')throw Error('Escolha uma data válida.');date=data.value;}
      else if(name==='calendar-span'){if(!['1','7'].includes(String(data.value)))return;span=Number(data.value);}
      else return;
      error='';notify();await refresh();
    }catch(e){error=e.message||'Não foi possível carregar a agenda.';busy=false;notify();toast(error);}
  }
  return {page,settings,action,enter:()=>error?Promise.resolve():refresh(),get enabled(){return prefs.value.enabled},snapshot:()=>({calendarDate:date,calendarSpan:span}),restore(view){if(validDate(view.calendarDate)&&view.calendarDate<='2200-12-24')date=view.calendarDate;if([1,7].includes(view.calendarSpan))span=view.calendarSpan;}};
}
